// Class 12 English Core - Flamingo Prose Chapter 2: Lost Spring
// Fully standardized to English Core Blueprint & AGENTS.md guidelines

export const c12EngF2HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(0, 198, 255, 0.22), rgba(0, 114, 255, 0.1)); border: 1.5px solid #00C6FF; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(0, 198, 255, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #00C6FF; color: #000; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">FLAMINGO &bull; PROSE CHAPTER 2</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">Lost Spring: Stories of Stolen Childhood</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By Anees Jung (Born 1964, Rourkela, India) &mdash; Grinding Poverty, Generational Exploitation &amp; The Stolen Bloom of Youth\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(0, 198, 255, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #00C6FF; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: Lost Spring\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #00C6FF;\">Author:</b> Anees Jung (Indian Author, Journalist &amp; Social Reformer)</div>\n      <div><b style=\"color: #00C6FF;\">Book Origin:</b> <i>Lost Spring: Stories of Stolen Childhood</i> (1987)</div>\n      <div><b style=\"color: #00C6FF;\">Setting 1:</b> Seemapuri (Transit slum on Delhi's periphery; 10,000 migrant ragpickers)</div>\n      <div><b style=\"color: #00C6FF;\">Setting 2:</b> Firozabad, UP (India's glass-blowing hub; 20,000 child furnace labourers)</div>\n      <div><b style=\"color: #00C6FF;\">Saheb-e-Alam:</b> Literally \"Lord of the Universe\" &mdash; Supreme situational irony for a destitute ragpicker</div>\n      <div><b style=\"color: #00C6FF;\">Mukesh:</b> Son of a blinded bangle-maker daring to dream of becoming a motor mechanic</div>\n      <div><b style=\"color: #00C6FF;\">Central Metaphor:</b> 'Spring' = The flowering, education &amp; spontaneous joy of innocent childhood</div>\n      <div><b style=\"color: #00C6FF;\">The Vicious Circle:</b> Nexus of moneylenders (sahukars), middlemen, police, bureaucrats &amp; politicians</div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Social Framework -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Socio-Economic Framework\n  </h2>\n  <p>\n    In <b style=\"color: #00C6FF;\">Lost Spring: Stories of Stolen Childhood</b>, celebrated Indian journalist and author <b style=\"color: #00C6FF;\">Anees Jung</b> presents an unvarnished, empathetic investigation into the grinding poverty and institutional neglect that condemn millions of underprivileged Indian children to lifelong bonded labor. Through two distinct, parallel narratives, Jung juxtaposes the plight of Bangladeshi refugee ragpickers in <b style=\"color: #00C6FF;\">Seemapuri</b> on the outskirts of Delhi against the multi-generational servitude of glass bangle-makers in <b style=\"color: #00C6FF;\">Firozabad</b>, Uttar Pradesh.\n  </p>\n  <p>\n    The master metaphor of the title &mdash; <b style=\"color: #00C6FF;\">'Lost Spring'</b> &mdash; compares human childhood to the vernal season of nature. Just as spring represents blooming life, color, regeneration, and unbounded natural beauty, childhood is the sacred period of life intended for physical growth, intellectual schooling, and carefree discovery. By exposing how systemic economic marginalization snuffs out this natural bloom, Jung crafts an indictment against a society that accepts child exploitation as customary tradition.\n  </p>\n\n  <!-- Section 2: Detailed Textual Commentary -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    2. Deep Narrative Analysis &amp; Thematic Exposition\n  </h2>\n\n  <h3 style=\"color: #00C6FF; font-size: 17px; margin: 20px 0 10px 0;\">(i) Part I: \"Sometimes I Find a Rupee in the Garbage\" &mdash; Saheb-e-Alam</h3>\n  <p>\n    The first segment focuses on <b style=\"color: #00C6FF;\">Saheb</b>, an impoverished young boy whom the author encounters daily scouring garbage dumps in her upscale neighborhood. Saheb's family arrived in India as refugees from the green fields of Dhaka, Bangladesh, after torrential monsoon storms swept away their village, homes, and crops in 1971. When the narrator casually asks Saheb why he doesn't attend school, he innocently replies that there are no schools in his slum, and when she glibly remarks, <i>\"If I start a school, will you come?\"</i>, Saheb enthusiastically agrees. Days later, when Saheb races up asking if her school is ready, the author is stricken with deep self-reproach, realizing how easy it is for the affluent to make hollow, unfulfillable promises to the vulnerable.\n  </p>\n  <p>\n    The author discovers his full name is <b style=\"color: #00C6FF;\">Saheb-e-Alam</b>, meaning <b style=\"color: #00C6FF;\">\"Lord of the Universe\"</b> &mdash; a supreme situational irony, as he wanders the scorching urban streets barefoot, leading an \"army of barefoot boys who appear like the morning birds and disappear at noon.\" When queried about their footwear, the boys offer casual rationalizations &mdash; one claims his mother did not bring them down from the shelf, another attributes it to tradition. Jung discerns that invoking 'tradition' is merely a psychological defense mechanism disguising perpetual destitution.\n  </p>\n  <p>\n    In <b style=\"color: #00C6FF;\">Seemapuri</b>, over 10,000 ragpickers reside in squalid structures of mud, tin, and tarpaulin devoid of running water, drainage, or sewage. For thirty years they have lived without legal land identity, yet they cling tenaciously to <b style=\"color: #00C6FF;\">ration cards</b> that put their names on voting lists and allow them to purchase cheap grain. For them, survival and food take absolute precedence over abstract legal identity. Furthermore, garbage possesses two radically different meanings: to the parents, it is a matter of daily bread and survival; to the children, it is wrapped in magic and wonder &mdash; each heap carrying the thrilling possibility of unearthing a rupee, a ten-rupee note, or a discarded toy.\n  </p>\n  <p>\n    The tragedy deepens when Saheb takes a job at a roadside tea stall, earning ₹800 a month and all his meals. Though economically provided for, the carefree sparkle in his eyes has evaporated. The <b style=\"color: #00C6FF;\">steel canister</b> he carries weighs far heavier than his old plastic garbage bag: the bag was his own; the canister belongs to his employer. Saheb is no longer his own master.\n  </p>\n\n  <h3 style=\"color: #00C6FF; font-size: 17px; margin: 20px 0 10px 0;\">(ii) Part II: \"I Want to Drive a Car\" &mdash; Mukesh of Firozabad</h3>\n  <p>\n    The second narrative shifts to <b style=\"color: #00C6FF;\">Firozabad</b>, the historic center of India's glass-blowing industry, where every family has toiled for generations around fiery kilns producing glass bangles for Indian women. Here, the author meets <b style=\"color: #00C6FF;\">Mukesh</b>, who boldly departs from the fatalistic resignation of his community by proclaiming: <i>\"I want to be a motor mechanic. I will go to a garage and learn.\"</i>\n  </p>\n  <p>\n    More than 20,000 children in Firozabad work unlawfully around blinding furnaces at extreme temperatures in dingy, unventilated cells lacking natural light and fresh air. Due to persistent exposure to furnace soot and microscopic glass dust during the polishing process, the vast majority lose their eyesight before reaching adult maturity. Visiting Mukesh's half-built ancestral home through choked, foul-smelling alleys, the author observes his family's destitution. Mukesh's father, after a lifetime of grueling labor first as a tailor and then as a bangle-maker, failed to repair his house or send his two sons to school; all he could bequeath was the rudimentary art of making bangles. Mukesh's grandmother accepts this blindness and poverty fatalistically as <b style=\"color: #00C6FF;\">\"karam\"</b> (destiny), asking: <i>\"Can a god-given lineage ever be broken?\"</i>\n  </p>\n  <p>\n    The author observes young <b style=\"color: #00C6FF;\">Savita</b>, a young girl soldering glass alongside an elderly woman. Her mechanical hands dart like tongs, entirely oblivious to the sacred marital sanctity of the bangles (symbolizing Indian womanhood's <i>suhaag</i>) that she will one day wear. When Jung asks the young men why they do not unionize or form a cooperative, they reveal the terrifying socio-political reality: if they attempt to organize, they are hauled up, beaten, and imprisoned by the police for doing something \"illegal\".\n  </p>\n  <p>\n    Jung concludes by analyzing the <b style=\"color: #00C6FF;\">\"two distinct worlds\"</b> that hold Firozabad in an iron grip: one is the web of inherited caste stigma and grinding poverty; the other is the ruthless <b style=\"color: #00C6FF;\">vicious circle of moneylenders (sahukars), middlemen, police, law enforcers, bureaucrats, and politicians</b>. Daring to dream is treated as dangerous insubordination. Yet in Mukesh's clear, steady eyes, the spark of rebellion survives: he dreams of cars, though sensibly, he does not harbor impossible fantasies of flying airplanes.\n  </p>\n\n  <!-- Section 3: Psychological & Character Profiles -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    3. Psychological &amp; Character Profiles\n  </h2>\n\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.35); border-radius: 8px; padding: 16px; margin-bottom: 16px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; margin: 0 0 6px 0; font-size: 16px;\">1. Saheb-e-Alam (The Trapped Drifter)</h4>\n    <p style=\"margin: 0; color: #CBD5E1; font-size: 14.5px;\">\n      <b>Psychological Complex:</b> Innocent, uncorrupted, and optimistic. Treats municipal refuse as an enchanted treasure hunt. However, he lacks institutional agency and ultimately trades his cherished freedom for economic sustenance, becoming a submissive wage laborer whose spirit is weighed down by the master's steel canister.\n    </p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.35); border-radius: 8px; padding: 16px; margin-bottom: 16px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; margin: 0 0 6px 0; font-size: 16px;\">2. Mukesh (The Defiant Dreamer)</h4>\n    <p style=\"margin: 0; color: #CBD5E1; font-size: 14.5px;\">\n      <b>Psychological Complex:</b> Determined, practical, and courageously rebellious. Unlike his fatalistic grandmother and defeated father, Mukesh possesses the psychological fortitude to challenge ancestral determinism. His dream of becoming a motor mechanic is tangible and realistic &mdash; grounded in the streets of Firozabad.\n    </p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.35); border-radius: 8px; padding: 16px; margin-bottom: 16px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; margin: 0 0 6px 0; font-size: 16px;\">3. Anees Jung (The Compassionate Chronicler)</h4>\n    <p style=\"margin: 0; color: #CBD5E1; font-size: 14.5px;\">\n      <b>Psychological Complex:</b> Self-aware, introspective, and socially engaged. She critically assesses her own bourgeois complacency when making hollow promises to Saheb, and uses investigative prose to deconstruct the oppressive institutional nexus exploiting child labor.\n    </p>\n  </div>\n\n  <!-- Section 4: Literary Devices Master Table -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    4. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(0, 198, 255, 0.25); color: #FFFFFF; border-bottom: 2px solid #00C6FF;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Thematic Function &amp; Critical Impact</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #00C6FF;\">Situational Irony</td>\n          <td style=\"padding: 10px 14px;\">\"His name is Saheb-e-Alam... Lord of the Universe.\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Exposes the tragic gulf between his celestial name and his wretched reality as a barefoot refuse scavenger.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #00C6FF;\">Metaphor</td>\n          <td style=\"padding: 10px 14px;\">\"Garbage to them is gold.\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Transforms foul, discarded refuse into life-sustaining currency, food, and miraculous survival.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #00C6FF;\">Metaphor</td>\n          <td style=\"padding: 10px 14px;\">\"Lost Spring\" (Title)</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Equates childhood innocence and schooling with the blossoming vernal season of life, ruthlessly stolen.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #00C6FF;\">Hyperbole</td>\n          <td style=\"padding: 10px 14px;\">\"An army of barefoot boys who appear like the morning birds...\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Magnifies their numbers while contrasting their morning vitality with noon disappearance into squalor.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #00C6FF;\">Symbolism</td>\n          <td style=\"padding: 10px 14px;\">\"Steel canister vs. Light plastic bag\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Plastic bag signifies self-directed freedom; the steel canister embodies the crushing burden of wage bondage.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #00C6FF;\">Sensory Imagery</td>\n          <td style=\"padding: 10px 14px;\">\"Glass furnaces with high temperatures, dingy cells without air and light\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Evokes visceral, claustrophobic sensations of blinding heat, noxious fumes, and physical decay.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 5: Thematic Pillars -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    5. Core Thematic Pillars &amp; Critical Insights\n  </h2>\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px;\">\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Grinding Destitution &amp; Migration</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Displaced by natural calamities in Bangladesh, 10,000 migrants in Seemapuri prioritize food over legal citizenship.</p>\n    </div>\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Fatalism vs. Determined Agency</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Older generations surrender to 'karma' and hereditary duty; Mukesh dares to break the mold by pursuing automotive mechanics.</p>\n    </div>\n    <div style=\"background: rgba(0, 198, 255, 0.08); border-left: 4px solid #00C6FF; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">The Nexus of Exploitation</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Police, bureaucrats, politicians, and moneylenders suppress unionization, criminalizing legitimate collective bargaining.</p>\n    </div>\n  </div>\n\n</div>\n";

export const c12EngF2HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Solutions Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(0, 198, 255, 0.22), rgba(0, 114, 255, 0.1)); border: 1.5px solid #00C6FF; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(0, 198, 255, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #00C6FF; color: #000; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">QUESTION BANK &bull; CHAPTER 2</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 24px; font-weight: 900; margin: 0 0 6px 0;\">Lost Spring &mdash; Complete Board Solutions</h1>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin: 0;\">\n      Standardized for CBSE &amp; JKBOSE • High-Scoring Extract, Short, Long Thematic &amp; Official NCERT Solutions\n    </p>\n  </div>\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    SECTION A: Extract-Based Questions (16 Questions | 4 Extracts)\n  </h2>\n\n  <!-- Extract 1 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #00C6FF;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #00C6FF;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"I have nothing else to do,\" he mutters, looking away. \"Go to school,\" I say glibly, realizing immediately how hollow the advice must sound. \"There is no school in my neighborhood. When they build one, I will go.\" \"If I start a school, will you come?\" I ask, half-joking. \"Yes,\" he says, smiling broadly. A few days later I see him running up to me. \"Is your school ready?\"\n    </p>\n    \n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q1: Why did the narrator describe her advice to 'go to school' as 'glib' and 'hollow'?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> The narrator realizes she gave superficial, unfeasible advice without grasping Saheb's severe poverty, lack of neighbourhood schools, and daily struggle for mere survival.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q2: What psychological effect did the narrator's broken promise have on her?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> She experienced deep embarrassment and guilt because her empty promise mirrored the numerous unfulfilled commitments privileged society habitually makes to destitute children.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q3: What does Saheb's broad, enthusiastic smile reveal about his disposition?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> It underscores his pure childhood innocence, natural optimism, and deep yearning for schooling and dignity despite squalor.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q4: Identify the dominant literary tone evident in this interaction.</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Pathos and gentle self-indictment, exposing the chasm between well-meaning bourgeois promises and harsh structural neglect.\n    </p>\n  </div>\n\n  <!-- Extract 2 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #00C6FF;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #00C6FF;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"It is his karam, his destiny,\" says Mukesh’s grandmother, who has watched her own husband go blind with the dust from polishing the glass of bangles. \"Can a god-given lineage ever be broken?\" she implies. Born in the caste of bangle makers, they have seen nothing but bangles &mdash; in the house, in the yard, in every other house, every other yard, every street in Firozabad.\n    </p>\n    \n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q5: What philosophical outlook governs Mukesh's grandmother's perspective?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Fatalistic resignation &mdash; the traditional belief that their suffering, caste occupation, and blindness are divinely ordained and unchallengeable.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q6: What specific occupational health hazard of the bangle industry is described?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Permanent loss of eyesight caused by constant inhalation and corneal injury from fine glass polishing dust.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q7: What rhetorical question does the grandmother pose, and what does it reveal?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> <i>\"Can a god-given lineage ever be broken?\"</i> It highlights the deep-rooted psychological conditioning that accepts generational exploitation without protest.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q8: Identify the stylistic device employed in the repeated phrasing \"in the house, in the yard...\".</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Repetition (Anaphora), underscoring the inescapable, suffocating ubiquity of bangles that engulfs every dimension of life in Firozabad.\n    </p>\n  </div>\n\n  <!-- Extract 3 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #00C6FF;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #00C6FF;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"I will learn to drive a car,\" he answers, looking straight into my eyes. His dream looms like a mirage amidst the dust of streets that fill his town Firozabad, famous for its bangles. Every other family in Firozabad is engaged in making bangles. It is the centre of India’s glass-blowing industry where families have spent generations working around furnaces...\n    </p>\n    \n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q9: What is Mukesh's declared ambition, and how does he express it?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> He resolves to become a motor mechanic and learn to drive, looking straight into the author's eyes with unwavering determination.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q10: Why is his dream compared to a 'mirage'?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Because it appears illusory, fragile, and nearly unattainable against the suffocating backdrop of hereditary servitude and institutional apathy in Firozabad.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q11: What industry constitutes the commercial heartbeat of Firozabad?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> The glass-blowing and glass bangle-manufacturing industry of India.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q12: How long have families been trapped in this occupation?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> For unbroken generations, passing down the craft without any socio-economic mobility.\n    </p>\n  </div>\n\n  <!-- Extract 4 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #00C6FF;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #00C6FF;\">Read the extract given below and answer the questions that follow:</b><br/>\n      Together they have imposed the baggage on the child that he cannot put down. Before he is aware, he accepts it as naturally as his father. To do anything else would mean to dare. And daring is not part of his growing up. When I sense a flash of it in Mukesh I am cheered. \"I want to be a motor mechanic,\" he repeats.\n    </p>\n    \n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q13: Who are 'they' that have imposed this baggage upon the child?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> The oppressive nexus comprising moneylenders (sahukars), middlemen, police officers, bureaucrats, and politicians.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q14: What is the 'baggage' referred to here?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> The crushing socio-economic burden of generational debt, caste obligation, and hazardous furnace labor.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q15: Why is 'daring' not part of a child's upbringing in Firozabad?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Because any attempt to rebel, question tradition, or unionize is brutally crushed with police violence and imprisonment.\n    </p>\n\n    <p>\n      <b style=\"color: #00C6FF; font-size: 15px;\">Q16: Why was the author cheered upon hearing Mukesh repeat his ambition?</b><br/>\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Because his defiance proved that the human spirit and desire for freedom can survive even within the bleakest circumstances.\n    </p>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION B: Short Answer Questions (3 Marks Each | 40&ndash;50 Words)\n  </h2>\n\n  <!-- Q17 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q17: What is the supreme situational irony hidden behind Saheb’s full name?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Saheb’s full name is <b style=\"color: #00C6FF;\">Saheb-e-Alam</b>, meaning \"Lord of the Universe\". The painful irony is that far from ruling the cosmos, he is a homeless, barefoot child scavenger foraging through hazardous urban garbage heaps on Delhi's periphery just to avoid starvation.\n    </p>\n  </div>\n\n  <!-- Q18 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q18: How does garbage possess two contrasting meanings for children and adults in Seemapuri?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> For adults, garbage is strictly an instrument of livelihood &mdash; their sole means of securing daily bread and roof over their heads. For innocent children like Saheb, garbage is wrapped in magic and wonder, as each heap holds the tantalizing possibility of finding an unexpected silver coin or ten-rupee note.\n    </p>\n  </div>\n\n  <!-- Q19 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q19: Why do the ragpickers of Seemapuri value ration cards above formal personal identity?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> For the 10,000 migrant refugees living in Seemapuri, immediate survival outweighs abstract constitutional identity. Ration cards place their names on voter registries and enable them to buy subsidized grain, preventing starvation and sustaining their families.\n    </p>\n  </div>\n\n  <!-- Q20 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q20: Why did Saheb lose his carefree spirit after joining the tea stall?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Although paid ₹800 monthly with meals, Saheb sacrificed his autonomy. The steel canister he carried belonged to the shopkeeper and felt far heavier than his own plastic bag. He was no longer his own master; wage servitude extinguished his youthful freedom.\n    </p>\n  </div>\n\n  <!-- Q21 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q21: What occupational hazards confront child workers in Firozabad’s glass factories?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Over 20,000 children labor around scorching furnaces in dark, ill-ventilated cells. The intense heat, absence of fresh air, and incessant inhalation of toxic glass polishing dust cause chronic pulmonary illnesses, burns, and permanent blindness before adulthood.\n    </p>\n  </div>\n\n  <!-- Q22 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q22: How do the barefoot children rationalize their lack of footwear, and how does Jung interpret it?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> The boys rationalize walking barefoot as a cultural tradition or claim their mothers did not bring down shoes from shelves. Anees Jung astutely discerns that calling it 'tradition' is merely an alibi to disguise perpetual, grinding poverty.\n    </p>\n  </div>\n\n  <!-- Q23 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q23: Who is Savita, and what profound cultural irony does her situation present?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Savita is a young girl soldering glass alongside an elderly woman. The poignant irony is that her mechanical hands solder bangles without understanding their auspicious sanctity as a symbol of an Indian bride's <i>suhaag</i>, which she will only discover on her wedding day.\n    </p>\n  </div>\n\n  <!-- Q24 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q24: What two distinct worlds does Anees Jung identify in Firozabad?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> The first is the world of the impoverished bangle-makers ensnared in caste stigma and poverty. The second is the vicious nexus of moneylenders (sahukars), middlemen, police, law enforcers, bureaucrats, and politicians who systematically prevent unionization.\n    </p>\n  </div>\n\n  <!-- Q25 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q25: How does Mukesh’s attitude differ markedly from that of his family and peers?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> While his community fatalistically surrenders to bangle-making as an unalterable divine destiny, Mukesh exhibits courage and personal agency. He refuses to inherit the furnace trade, resolving firmly to walk miles to a garage to become a motor mechanic.\n    </p>\n  </div>\n\n  <!-- Q26 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q26: Why does Mukesh’s ambition stop at becoming a motor mechanic instead of flying airplanes?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Mukesh is sensible and grounded. He frequently sees cars rattling along the dusty roads of Firozabad, making a mechanic's trade tangible and within reach. Airplanes rarely fly over Firozabad, placing aviation completely beyond his frame of reference.\n    </p>\n  </div>\n\n  <!-- Q27 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q27: What has Mukesh's father achieved after a lifetime of hard labor?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Despite years of back-breaking toil, first as a tailor and then as a bangle-maker, Mukesh's father failed to renovate his dilapidated house or send his sons to school. His only accomplishment was teaching them the craft of making bangles.\n    </p>\n  </div>\n\n  <!-- Q28 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q28: Why do young men in Firozabad fail to organize themselves into cooperatives?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> If they attempt to organize, they are hunted down, beaten, and jailed by the police under false charges of doing something illegal. They lack leadership and are terrorized by the corrupt nexus of sahukars, middlemen, and bureaucrats.\n    </p>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION C: Long Answer Questions (6 Marks Each | 120&ndash;150 Words)\n  </h2>\n\n  <!-- Q29 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q29: Justify the title 'Lost Spring: Stories of Stolen Childhood' with detailed textual evidence.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Introduction &amp; Metaphorical Context:</b><br/>\n        Spring is universally acclaimed as the season of blossoming flora, vernal renewal, and youthful exuberance. In human life, childhood corresponds directly to spring &mdash; a formative, carefree chapter meant for formal education, creative play, physical health, and emotional nurture. Anees Jung uses 'Lost Spring' as an evocative metaphor to highlight how destitution and institutional apathy mercilessly snuff out the bloom of youth.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Textual Exploration:</b><br/>\n        Through two distinct narratives, Jung exposes how the spring of youth is stolen. In Seemapuri, Saheb wanders barefoot through filthy garbage dumps, forfeiting schooling for mere survival. Later, at the tea stall, his spontaneous joy is crushed under the weight of an employer's steel canister. In Firozabad, over 20,000 children sit in dark, suffocating furnace chambers, their eyesight ruined before adulthood by scorching heat and toxic glass dust.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #00C6FF;\">Conclusion &amp; Critical Verdict:</b><br/>\n        Denied the basic constitutional rights to literacy, play, and health, these children are prematurely thrust into adult toil. Thus, their 'spring' is permanently lost to systemic poverty and social indifference, making the title supremely poignant and apt.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q30 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q30: Analyze the role of the 'Vicious Circle' in perpetuating the exploitation of bangle makers in Firozabad.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Introduction &amp; Socio-Political Framework:</b><br/>\n        In Firozabad, child labor and chronic destitution are not isolated socio-economic accidents; they are systematically enforced conditions perpetuated by an impenetrable nexus of vested interests termed the 'vicious circle'.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Components of the Exploitative Nexus:</b><br/>\n        First, the <b>sahukars (moneylenders)</b> ensnare illiterate families in perpetual generational debt through extortionate interest rates. Second, <b>middlemen</b> act as predatory gatekeepers, monopolizing trade and preventing artisans from accessing direct markets. Third, the <b>police and state machinery</b> brutally suppress any collective organizing; attempts to form cooperatives are deemed 'illegal', resulting in beatings and imprisonment. Finally, <b>bureaucrats and politicians</b> maintain deliberate legislative inaction, refusing to enforce anti-child labor statutes.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #00C6FF;\">Conclusion &amp; Psychological Impact:</b><br/>\n        This institutional web imposes an inescapable burden on young children, crushing their willpower before they mature and ensuring that hazardous furnace labor remains an unchallengeable ancestral inheritance.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q31 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q31: Compare and contrast the characters, agency, and life trajectories of Saheb-e-Alam and Mukesh.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Introduction &amp; Comparative Focus:</b><br/>\n        While both Saheb-e-Alam and Mukesh are victims of extreme social marginalization and child labor, their psychological dispositions and personal agency present a stark contrast between passive surrender and defiant determination.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Saheb vs. Mukesh &mdash; Core Comparison:</b><br/>\n        <b>Saheb-e-Alam</b> is a passive drifter who lives by momentary opportunities. He scavenges through garbage, rationalizes his barefoot status, and readily yields to external forces. When offered ₹800 at a tea stall, he surrenders his autonomy; the steel canister he carries marks his transition into bonded wage labor. In sharp contrast, <b>Mukesh</b> is a rebel against fatalism. Refusing to accept bangle-making as an unalterable divine decree, he asserts: <i>\"I will be a motor mechanic.\"</i> He exhibits practical ambition, prepared to walk miles to an automotive garage to acquire vocational skills.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #00C6FF;\">Critical Conclusion:</b><br/>\n        While Saheb represents compromised innocence yielding to economic servitude, Mukesh embodies the resilient flame of individual agency daring to challenge systemic injustice.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q32 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q32: Examine the living conditions and existential dilemma of the Bangladeshi refugees in Seemapuri.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Geographical &amp; Infrastructural Squalor:</b><br/>\n        Seemapuri stands on the physical periphery of Delhi, yet metaphorically remains light-years away from the capital's modern prosperity. Over 10,000 refugees reside in crude mud hovels with roofs of tin and tarpaulin, completely devoid of sewage, drainage, or running tap water.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">The Primacy of Food Over Identity:</b><br/>\n        Having fled devastating floods in Dhaka in 1971, these migrants value food far above legal citizenship. Ration cards serve as their lifeline, allowing them to purchase subsidized grain and appear on voter lists. Over three decades, ragpicking has acquired the status of a fine art &mdash; garbage is literally their \"gold\", providing daily sustenance and temporary shelter.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #00C6FF;\">Critical Conclusion:</b><br/>\n        Their existential plight exposes the stark failure of post-colonial urbanization, where thousands are reduced to human refuse scavengers to keep starvation at bay.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q33 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q33: How does the author expose the hollow promises made by affluent society to impoverished children?</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">The Incident of the Half-Joking Promise:</b><br/>\n        When the author casually asks Saheb why he does not attend school, she realizes how glib her remark is. In a moment of casual thoughtlessness, she asks, <i>\"If I start a school, will you come?\"</i> To her surprise, Saheb smiles broadly and eagerly agrees. Days later, he bounds up to her, enthusiastically inquiring if her school is ready.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Self-Indictment &amp; Societal Reflection:</b><br/>\n        The encounter strikes the author with acute embarrassment and remorse. She acknowledges that promises made to marginalized children abound in every corner of their bleak world, yet are almost never meant to be honored. Affluent individuals casually offer sympathetic platitudes without ever committing to tangible structural change.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #00C6FF;\">Critical Conclusion:</b><br/>\n        Anees Jung uses her own moral discomfort to indict the broader bourgeois complacency that placates impoverished children with empty words while leaving systemic deprivation untouched.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q34 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(0, 198, 255, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q34: Discuss the cultural symbolism of bangles versus the brutal reality of their manufacture in Firozabad.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">Auspicious Cultural Symbolism:</b><br/>\n        In traditional Indian culture, glass bangles represent female auspiciousness, marital sanctity, and prosperity &mdash; the sacred emblem of <i>suhaag</i>. Every Indian bride wears shimmering bangles of red, green, and gold on her wedding day to symbolize happiness and familial blessing.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #00C6FF;\">The Brutal Reality of Manufacture:</b><br/>\n        In tragic contrast, these symbols of matrimonial celebration are forged in hellish conditions. Over 20,000 children and adults labor in pitch-dark, suffocating furnace cells, burning their skin and sacrificing their eyesight to micro-fine glass dust. Young girls like Savita mechanically weld glass rings without comprehending their sanctity, destined to lose their vision before they ever become brides themselves.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #00C6FF;\">Critical Conclusion:</b><br/>\n        The beauty and auspiciousness adorning middle-class brides across India are extracted at the horrific cost of the health, sight, and childhood of Firozabad's youth.\n      </p>\n    </div>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <h2 style=\"color: #00C6FF; font-size: 20px; font-weight: 800; border-bottom: 2px solid #00C6FF; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION D: NCERT Textbook Exercises (Think As You Read &amp; Understanding The Text)\n  </h2>\n\n  <!-- Q35 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q35: What is Saheb looking for in the garbage dumps? Where is he and where has he come from?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Saheb is scouring the garbage dumps for valuables &mdash; silver coins, stray currency notes, or usable discarded articles that represent \"gold\" for his family's survival. He currently lives in Seemapuri, a transit slum on Delhi's eastern border. He migrated with his mother from Dhaka, Bangladesh, after violent storms destroyed their home and green fields in 1971.\n    </p>\n  </div>\n\n  <!-- Q36 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q36: What makes the city of Firozabad famous across India?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Firozabad is celebrated as the historic heart of India's glass-blowing and bangle-manufacturing industry. Almost every household has spent generations welding glass, working around fiery kilns, and creating colorful bangles that supply women across the entire country.\n    </p>\n  </div>\n\n  <!-- Q37 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q37: Mention the major occupational hazards of working in the glass bangles industry.</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> The foremost hazards include: (1) Permanent blindness caused by corneal scratches and inhaling micro-fine glass polishing dust; (2) Chronic respiratory illnesses from working in unventilated, oxygen-deprived cells; (3) Severe burn injuries from roaring furnace kilns exceeding hundreds of degrees; and (4) Stunted physical development in child laborers working 12&ndash;14 hours daily.\n    </p>\n  </div>\n\n  <!-- Q38 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #00C6FF;\">\n    <h4 style=\"color: #00C6FF; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q38: How, in your opinion, can Mukesh realize his dream of becoming a motor mechanic?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #00C6FF; font-weight: bold;\">✓ Answer:</span> Mukesh can realize his dream through his unwavering determination and practical mindset. By walking the long distance to a garage, serving as an apprentice under skilled mechanics, and persevering despite lack of family support, he can master automotive repair. His willingness to break free from fatalism provides the internal agency needed to overcome social adversity.\n    </p>\n  </div>\n\n</div>\n";

